"use strict";

// Validates full-backup structure. Domain validators are explicit dependencies;
// this module does not access DOM, live workspace state or IndexedDB.
globalThis.EduFullBackupValidator = Object.freeze({
  create({
    backupStores,
    assertSafeDataTree,
    isDataObject,
    isSafeRecordId,
    validateReportNotes,
    decodeWorkspaceRecords,
    validateFrozenReport,
    normalizeDB,
    validatedUndoCandidate,
    isSupportedGradeDraft,
  }) {
    // Canonicalize only declared year fields on a detached copy. This is also
    // used by startup migration without rewriting grades or historical events.
    function normalizeYears(value) {
      assertSafeDataTree(value);
      const candidate = structuredClone(value),
        pending = [{ kind: "installation", value: candidate }],
        seen = new WeakSet();
      const yearField = (object, key) => {
        if (isDataObject(object) && object[key] !== undefined)
          object[key] = EduAcademicYear.normalize(object[key]);
      };
      const lessonYears = (lesson, frozen = false) => {
        if (!isDataObject(lesson)) return;
        yearField(lesson.courseInfo, "year");
        yearField(frozen ? lesson.policy : lesson.gradingPolicy, "year");
      };
      const classYears = (classroom) => {
        if (Array.isArray(classroom?.lessons))
          for (const lesson of classroom.lessons) lessonYears(lesson);
      };
      const recordYears = (logical, record) => {
        if (logical === "meta") yearField(record?.settings, "academicYear");
        else if (typeof logical === "string" && logical.startsWith("class:"))
          classYears(record);
      };
      while (pending.length) {
        const job = pending.pop(),
          item = job.value;
        if (!isDataObject(item) || seen.has(item)) continue;
        seen.add(item);
        if (job.kind === "database") {
          yearField(item.settings, "academicYear");
          if (Array.isArray(item.schools))
            for (const school of item.schools)
              if (Array.isArray(school?.classes))
                for (const classroom of school.classes) classYears(classroom);
          continue;
        }
        if (job.kind === "report") {
          yearField(item, "year");
          if (Array.isArray(item.classes))
            for (const classroom of item.classes)
              if (Array.isArray(classroom?.students))
                for (const student of classroom.students)
                  if (Array.isArray(student?.lessons))
                    for (const lesson of student.lessons)
                      lessonYears(lesson, true);
          continue;
        }
        const stores = item.stores;
        if (!isDataObject(stores)) continue;
        if (Array.isArray(stores.catalog))
          for (const period of stores.catalog) yearField(period, "year");
        if (Array.isArray(stores.records))
          for (const record of stores.records)
            recordYears(record?.logical, record?.value);
        if (Array.isArray(stores.undo))
          for (const undo of stores.undo)
            if (Array.isArray(undo?.before))
              for (const before of undo.before)
                recordYears(before?.key, before?.value);
        if (Array.isArray(stores.reports))
          for (const report of stores.reports)
            pending.push({ kind: "report", value: report });
        if (Array.isArray(stores.backups))
          for (const backup of stores.backups) {
            if (isDataObject(backup?.db))
              pending.push({ kind: "database", value: backup.db });
            if (backup?.full?.format === "EduManager.FullBackup")
              pending.push({ kind: "installation", value: backup.full });
          }
      }
      return candidate;
    }
    function validateCanonicalFullBackup(value) {
      if (
        value?.format !== "EduManager.FullBackup" ||
        ![1, 2].includes(value.version) ||
        ![25, 26].includes(value.schemaVersion)
      )
        throw Error("ساختار پشتیبان کامل پشتیبانی نمی‌شود.");
      assertSafeDataTree(value);
      for (const name of backupStores)
        if (!Array.isArray(value.stores?.[name]))
          throw Error("بخش پشتیبان ناقص است: " + name);
      if (
        value.reportDrafts !== undefined &&
        (!value.reportDrafts ||
          typeof value.reportDrafts !== "object" ||
          Array.isArray(value.reportDrafts))
      )
        throw Error("فهرست توضیحات پشتیبان معتبر نیست.");
      const ids = new Set(),
        recordsByWorkspace = new Map(),
        recordSets = new Map(),
        periods = [];
      for (const row of value.stores.records) {
        if (!isDataObject(row) || !isSafeRecordId(row.workspace))
          throw Error("رکورد داده باید متعلق به یک دوره معتبر باشد.");
        if (!recordsByWorkspace.has(row.workspace))
          recordsByWorkspace.set(row.workspace, []);
        recordsByWorkspace.get(row.workspace).push(row);
      }
      for (const period of value.stores.catalog) {
        if (
          !isDataObject(period) ||
          !isSafeRecordId(period.id) ||
          ids.has(period.id) ||
          !Number.isSafeInteger(period.revision) ||
          period.revision < 0 ||
          typeof period.closed !== "boolean" ||
          typeof period.createdAt !== "string" ||
          !Number.isFinite(Date.parse(period.createdAt))
        )
          throw Error("شناسنامه دوره در پشتیبان نامعتبر است.");
        if (
          period.termKind != null &&
          !["first", "second", "summer"].includes(period.termKind)
        )
          throw Error("نوع نوبت تحصیلی در پشتیبان معتبر نیست.");
        validateReportNotes(period.reportNotesRecovery, period.id);
        if (
          period.reportSource != null &&
          !["primary", "secondary"].includes(period.reportSource)
        )
          throw Error("نوع منبع گزارش در پشتیبان معتبر نیست.");
        validateReportNotes(value.reportDrafts?.[period.id], period.id);
        ids.add(period.id);
        const records = recordsByWorkspace.get(period.id) || [];
        const logical = new Map(records.map((r) => [r.logical, r.value]));
        const meta = logical.get("meta");
        if (
          !meta ||
          !Array.isArray(meta.layout) ||
          logical.size !== records.length ||
          records.some((r) => r.key !== period.id + "|" + r.logical)
        )
          throw Error("رکوردهای دوره ناقص یا تکراری است.");
        const normalized = decodeWorkspaceRecords(records, {
          workspaceId: period.id,
        }).data;
        recordSets.set(
          period.id,
          new Map(records.map((row) => [row.logical, row.value])),
        );
        if (
          normalized.settings.academicYear !== period.year ||
          normalized.settings.academicTerm !== period.term
        )
          throw Error("عنوان دوره با اطلاعات پشتیبان سازگار نیست.");
        periods.push({ period, data: normalized });
      }
      if (Object.keys(value.reportDrafts || {}).some((id) => !ids.has(id)))
        throw Error("توضیحات گزارش متعلق به دوره ناموجود است.");
      if (!periods.length || !ids.has(value.activeWorkspace))
        throw Error("دوره فعال پشتیبان موجود نیست.");
      for (const name of ["records", "events", "undo", "reports", "backups"])
        for (const row of value.stores[name]) {
          if (
            !isDataObject(row) ||
            (row.workspace != null && !ids.has(row.workspace))
          )
            throw Error("رکورد خارج از دوره‌های پشتیبان است.");
          if (name === "undo" && !ids.has(row.id))
            throw Error("شناسه بازگردانی نامعتبر است.");
          if (
            name === "events" &&
            (typeof row.action !== "string" ||
              row.action.length > 10000 ||
              typeof row.at !== "string" ||
              !Number.isFinite(Date.parse(row.at)) ||
              (row.revision !== undefined &&
                (!Number.isSafeInteger(row.revision) || row.revision < 0)) ||
              !Array.isArray(row.changes) ||
              row.changes.some(
                (change) =>
                  !isDataObject(change) ||
                  typeof change.path !== "string" ||
                  change.path.length > 10000,
              ))
          )
            throw Error("ساختار تاریخچه پشتیبان معتبر نیست.");
          if (name === "reports") {
            if (!ids.has(row.workspace))
              throw Error("کارنامه ثابت متعلق به دوره موجود نیست.");
            validateFrozenReport(row);
          }
          if (name === "backups" && !row.full)
            normalizeDB(row.db, {
              legacy: (row.db?.schemaVersion || 23) < 24,
            });
        }
      const undoIds = new Set();
      for (const undo of value.stores.undo) {
        if (undoIds.has(undo.id))
          throw Error("رکورد بازگردانی دوره تکراری است.");
        undoIds.add(undo.id);
        const period = periods.find(
          (item) => item.period.id === undo.id,
        )?.period;
        validatedUndoCandidate(undo, recordSets.get(undo.id), period);
      }
      if (value.version === 2 && !Array.isArray(value.gradeDrafts))
        throw Error("بخش پیش‌نویس نمره پشتیبان ناقص است.");
      const draftKeys = new Set();
      for (const row of value.gradeDrafts || []) {
        if (
          !isDataObject(row) ||
          !ids.has(row.workspace) ||
          typeof row.key !== "string" ||
          !row.key.startsWith("Edu24.drafts." + row.workspace + ".") ||
          draftKeys.has(row.key) ||
          !Number.isSafeInteger(row.generation) ||
          row.generation < 0 ||
          !Array.isArray(row.entries) ||
          !row.entries.every(isSupportedGradeDraft) ||
          typeof row.updatedAt !== "string"
        )
          throw Error("پیش‌نویس نمره پشتیبان نامعتبر است.");
        draftKeys.add(row.key);
      }
      return periods;
    }
    function validateFullBackup(value) {
      return validateCanonicalFullBackup(normalizeYears(value));
    }
    validateFullBackup.normalizeYears = normalizeYears;
    validateFullBackup.normalize = (value) => {
      const candidate = normalizeYears(value);
      validateCanonicalFullBackup(candidate);
      return candidate;
    };
    return Object.freeze(validateFullBackup);
  },
});
